import type {
  IsoTimestamp,
  NotificationId,
  TenantScoped,
  Timestamps,
  UserId,
} from "./common";

export type NotificationKind =
  | "issue_assigned"
  | "issue_status_changed"
  | "issue_due_soon"
  | "issue_overdue"
  | "comment_created"
  | "comment_mention"
  | "member_invited"
  | "member_joined"
  | "project_archived"
  | "plan_limit_reached"
  | "digest_ready";

export type NotificationChannel = "in_app" | "email" | "webhook";

export interface Notification extends Timestamps, TenantScoped {
  readonly id: NotificationId;
  readonly recipientId: UserId;
  readonly kind: NotificationKind;
  readonly title: string;
  readonly body: string;
  readonly href: string;
  readonly actorId: UserId | null;
  readonly readAt: IsoTimestamp | null;
  readonly channels: readonly NotificationChannel[];
}

/** Per-user delivery matrix; the fan-out consults this before every send. */
export interface NotificationPreference extends TenantScoped {
  readonly userId: UserId;
  readonly kind: NotificationKind;
  readonly inApp: boolean;
  readonly email: boolean;
  readonly digestOnly: boolean;
}

/** One item queued for the daily digest email. */
export interface DigestEntry {
  readonly notificationId: NotificationId;
  readonly kind: NotificationKind;
  readonly title: string;
  readonly href: string;
  readonly occurredAt: IsoTimestamp;
}

export interface DigestBundle extends TenantScoped {
  readonly recipientId: UserId;
  readonly entries: readonly DigestEntry[];
  readonly windowStart: IsoTimestamp;
  readonly windowEnd: IsoTimestamp;
}

import { index, integer, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import { idColumn, softDeleteColumns, timestampColumns } from "./_shared";

export const organizations = sqliteTable(
  "organizations",
  {
    id: idColumn(),
    name: text("name").notNull(),
    slug: text("slug").notNull(),
    ownerId: text("owner_id").notNull(),
    plan: text("plan", {
      enum: ["free", "starter", "growth", "enterprise"],
    })
      .notNull()
      .default("free"),
    logoUrl: text("logo_url"),
    trialEndsAt: text("trial_ends_at"),
    defaultIssueStatus: text("default_issue_status").notNull().default("backlog"),
    allowPublicProjects: integer("allow_public_projects", { mode: "boolean" })
      .notNull()
      .default(false),
    requireTwoFactor: integer("require_two_factor", { mode: "boolean" })
      .notNull()
      .default(false),
    digestHourUtc: integer("digest_hour_utc").notNull().default(7),
    enabledFlagOverrides: text("enabled_flag_overrides").notNull().default("[]"),
    ...timestampColumns,
    ...softDeleteColumns,
  },
  (table) => [
    uniqueIndex("organizations_slug_idx").on(table.slug),
    index("organizations_owner_idx").on(table.ownerId),
  ],
);

export const organizationUsage = sqliteTable("organization_usage", {
  orgId: text("org_id").primaryKey(),
  seatsUsed: integer("seats_used").notNull().default(0),
  projectsUsed: integer("projects_used").notNull().default(0),
  issuesUsed: integer("issues_used").notNull().default(0),
  storageMbUsed: integer("storage_mb_used").notNull().default(0),
  measuredAt: text("measured_at").notNull(),
});

export type OrganizationRow = typeof organizations.$inferSelect;
export type NewOrganizationRow = typeof organizations.$inferInsert;
export type OrganizationUsageRow = typeof organizationUsage.$inferSelect;

import { index, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import {
  idColumn,
  softDeleteColumns,
  tenantColumns,
  timestampColumns,
} from "./_shared";

export const members = sqliteTable(
  "members",
  {
    id: idColumn(),
    ...tenantColumns,
    userId: text("user_id").notNull(),
    role: text("role", { enum: ["owner", "admin", "member", "viewer"] })
      .notNull()
      .default("member"),
    status: text("status", { enum: ["active", "invited", "suspended"] })
      .notNull()
      .default("active"),
    invitedBy: text("invited_by"),
    joinedAt: text("joined_at"),
    lastSeenAt: text("last_seen_at"),
    ...timestampColumns,
    ...softDeleteColumns,
  },
  (table) => [
    uniqueIndex("members_org_user_idx").on(table.orgId, table.userId),
    index("members_org_role_idx").on(table.orgId, table.role),
  ],
);

export const invitations = sqliteTable(
  "invitations",
  {
    id: idColumn(),
    ...tenantColumns,
    email: text("email").notNull(),
    role: text("role", { enum: ["owner", "admin", "member", "viewer"] })
      .notNull()
      .default("member"),
    invitedBy: text("invited_by").notNull(),
    tokenHash: text("token_hash").notNull(),
    expiresAt: text("expires_at").notNull(),
    acceptedAt: text("accepted_at"),
    revokedAt: text("revoked_at"),
    ...timestampColumns,
  },
  (table) => [
    uniqueIndex("invitations_token_idx").on(table.tokenHash),
    index("invitations_org_email_idx").on(table.orgId, table.email),
  ],
);

export type MemberRow = typeof members.$inferSelect;
export type NewMemberRow = typeof members.$inferInsert;
export type InvitationRow = typeof invitations.$inferSelect;

import { text } from "drizzle-orm/sqlite-core";

/**
 * Column fragments every Taskflow table reuses.
 *
 * Conventions enforced here:
 *  - ids are ULID text primary keys
 *  - timestamps are ISO-8601 text, not unix integers
 *  - every tenant-scoped table carries `org_id`
 *  - every soft-deletable table carries `archived_at`
 */

export const nowIso = () => new Date().toISOString();

export const idColumn = (name = "id") => text(name).primaryKey();

export const timestampColumns = {
  createdAt: text("created_at").notNull().$defaultFn(nowIso),
  updatedAt: text("updated_at").notNull().$defaultFn(nowIso),
};

/** Spread into every table that belongs to exactly one organization. */
export const tenantColumns = {
  orgId: text("org_id").notNull(),
};

/** Spread into every table that is archived rather than deleted. */
export const softDeleteColumns = {
  archivedAt: text("archived_at"),
};

