/** Why an ownership-handover operation was refused; see `OwnershipHandoverError`. */
export type OwnershipHandoverRefusal =
  | "self"
  | "pending_exists"
  | "nothing_pending"
  | "expired";

/** Thrown by the ownership-handover flow's guard clauses. */
export class OwnershipHandoverError extends Error {
  readonly code = "conflict" as const;

