 * lapsed one does not count and is lazily marked `expired` here so it stops
 * blocking a fresh offer.
 */
export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  assertIsRecordedOwner(actor, org);

  const now = toIsoTimestamp(new Date());
  const existing = await handoverRepo.findPendingHandover(orgId);
  if (existing) {
    if (existing.expiresAt <= now) {
      await handoverRepo.resolveHandover(orgId, existing.id, "expired", null);
    } else {
      throw new OwnershipHandoverError("pending_exists");
    }
  }

  if (toUserId === actor.userId) {
    throw new OwnershipHandoverError("self");
  }

  const target = requireFound(
    await memberRepo.findMember(orgId, toUserId),
    "Member",
    toUserId,
  );
  if (target.status !== "active") {
    throw new NotFoundError("Member", toUserId);
  }

  const handover = await handoverRepo.insertHandover(
    orgId,
    actor.userId,
    toUserId,
  );

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "You've been offered workspace ownership",
    body: `${actor.userId} wants to hand this workspace's ownership over to you`,
    href: "/settings/members",
    actorId: actor.userId,
  });

  return handover;
}

/**
 * Accepts the open offer made to the caller. Promotes the accepting member to
 * owner first (if they are not already one) and only then steps the previous
 * owner down, so the workspace is never briefly without an owner.
 */
export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);

  const now = toIsoTimestamp(new Date());
  const existing = await handoverRepo.findPendingHandover(orgId);
  if (!existing || existing.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  if (existing.expiresAt <= now) {
    await handoverRepo.resolveHandover(orgId, existing.id, "expired", null);
    throw new OwnershipHandoverError("expired");
  }

  const toMember = requireFound(
    await memberRepo.findMember(orgId, actor.userId),
    "Member",
    actor.userId,
  );

  if (toMember.role !== "owner") {
    const updated = await memberRepo.updateMemberRole(
      orgId,
      toMember.id,
      "owner",
    );
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: updated.id,
      from: toMember.role,
      to: updated.role,
    });
  }

  const fromMember = await memberRepo.findMember(orgId, existing.fromUserId);
  if (fromMember && fromMember.role === "owner") {
    const updated = await memberRepo.updateMemberRole(
      orgId,
      fromMember.id,
      "admin",
    );
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: updated.id,
      from: fromMember.role,
      to: updated.role,
    });
  }

  const org = await orgRepo.updateOrgOwner(orgId, actor.userId);
  await handoverRepo.resolveHandover(orgId, existing.id, "accepted", now);

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: existing.fromUserId,
    toUserId: actor.userId,
  });

  return org;
}

/** Declines the open offer made to the caller. */
export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const now = toIsoTimestamp(new Date());
  const existing = await handoverRepo.findPendingHandover(orgId);
  if (!existing || existing.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  if (existing.expiresAt <= now) {
    await handoverRepo.resolveHandover(orgId, existing.id, "expired", null);
    throw new OwnershipHandoverError("expired");
  }

  return handoverRepo.resolveHandover(orgId, existing.id, "declined", now);
}

/** Withdraws the offer the caller made. Only the recorded owner may do this. */
export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  assertIsRecordedOwner(actor, org);

  const now = toIsoTimestamp(new Date());
  const existing = await handoverRepo.findPendingHandover(orgId);
  if (!existing) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  if (existing.expiresAt <= now) {
    await handoverRepo.resolveHandover(orgId, existing.id, "expired", null);
    throw new OwnershipHandoverError("expired");
  }

  return handoverRepo.resolveHandover(orgId, existing.id, "canceled", now);
}

/** The org's open offer, or `null`. Visible to any member of the workspace. */
export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);

  const existing = await handoverRepo.findPendingHandover(orgId);
  if (!existing) return null;

  const now = toIsoTimestamp(new Date());
  if (existing.expiresAt <= now) {
    await handoverRepo.resolveHandover(orgId, existing.id, "expired", null);
    return null;
  }

  return existing;
}

