/**
 * Only the recorded owner — `organizations.ownerId`, not merely someone who
 * holds the `owner` role — may offer or withdraw a handover. Both failure
 * modes are a `PermissionDeniedError`.
 */
function assertIsRecordedOwner(actor: Actor, org: Organization): void {
  assertCan(actor, "org:manage_ownership", orgResource(org.id));

  if (actor.userId !== org.ownerId) {
    throw new PermissionDeniedError("org:manage_ownership", {
      allowed: false,
      action: "org:manage_ownership",
      resourceKind: "organization",
      reason: "denied_by_role",
    });
  }
}

