import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("./tests/server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("./tests/server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { OwnershipHandoverError } from "@/lib/errors";
import { PermissionDeniedError } from "@/lib/permissions";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgService from "@/server/services/organization-service";
import * as memberService from "@/server/services/member-service";
import { createTenant, useTemporaryDatabase } from "./tests/server/_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("smoke: ownership handover", () => {
  it("full accept flow", async () => {
    const tenant = await createTenant("handover-smoke", "growth");

    // non-owner cannot initiate
    await expect(
      orgService.initiateOwnershipHandover(tenant.actors.admin, tenant.org.id, tenant.userIds.member),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    // owner offering to self -> "self"
    await expect(
      orgService.initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.owner),
    ).rejects.toMatchObject({ reason: "self" });

    const offer = await orgService.initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.admin);
    expect(offer.status).toBe("pending");
    expect(offer.toUserId).toBe(tenant.userIds.admin);

    // second offer refused
    await expect(
      orgService.initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.member),
    ).rejects.toMatchObject({ reason: "pending_exists" });

    // wrong person accepting
    await expect(
      orgService.acceptOwnershipHandover(tenant.actors.member, tenant.org.id),
    ).rejects.toMatchObject({ reason: "nothing_pending" });

    const pending = await orgService.getPendingOwnershipHandover(tenant.actors.viewer, tenant.org.id);
    expect(pending?.id).toBe(offer.id);

    let roleChanges: unknown[] = [];
    const off1 = subscribe("member.role_changed", (p) => roleChanges.push(p));
    let transferred: unknown = null;
    const off2 = subscribe("organization.ownership_transferred", (p) => { transferred = p; });

    const org = await orgService.acceptOwnershipHandover(tenant.actors.admin, tenant.org.id);
    off1(); off2();

    expect(org.ownerId).toBe(tenant.userIds.admin);
    expect(roleChanges).toMatchObject([
      { memberId: expect.any(String), from: "admin", to: "owner" },
      { memberId: expect.any(String), from: "owner", to: "admin" },
    ]);
    expect(transferred).toMatchObject({ fromUserId: tenant.userIds.owner, toUserId: tenant.userIds.admin });

    const oldOwnerMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    expect(oldOwnerMember?.role).toBe("admin");
    const newOwnerMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    expect(newOwnerMember?.role).toBe("owner");

    // nothing pending now
    await expect(
      orgService.declineOwnershipHandover(tenant.actors.admin, tenant.org.id),
    ).rejects.toMatchObject({ reason: "nothing_pending" });

    // old owner (now admin) can be removed like any admin
    const removed = await memberService.removeMember(
      { userId: tenant.userIds.admin, orgId: tenant.org.id, role: "owner" },
      { orgId: tenant.org.id, memberId: oldOwnerMember!.id },
    );
    expect(removed.status).toBe("suspended");
  });

  it("decline, cancel, and auto-withdraw on removal", async () => {
    const tenant = await createTenant("handover-smoke-2", "growth");

    const offer1 = await orgService.initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.admin);
    const declined = await orgService.declineOwnershipHandover(tenant.actors.admin, tenant.org.id);
    expect(declined.status).toBe("declined");
    expect(declined.id).toBe(offer1.id);

    // owner may offer again after decline
    const offer2 = await orgService.initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.member);
    const canceled = await orgService.cancelOwnershipHandover(tenant.actors.owner, tenant.org.id);
    expect(canceled.status).toBe("canceled");
    expect(canceled.id).toBe(offer2.id);

    // withdrawing again -> nothing_pending
    await expect(
      orgService.cancelOwnershipHandover(tenant.actors.owner, tenant.org.id),
    ).rejects.toMatchObject({ reason: "nothing_pending" });

    // auto-withdraw: offer a third member, then remove them
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    const offer3 = await orgService.initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.viewer);
    await memberService.removeMember(tenant.actors.owner, { orgId: tenant.org.id, memberId: target!.id });

    const pendingAfterRemoval = await orgService.getPendingOwnershipHandover(tenant.actors.owner, tenant.org.id);
    expect(pendingAfterRemoval).toBeNull();

    // owner can now offer again (previous auto-withdrawn)
    const offer4 = await orgService.initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.member);
    expect(offer4.status).toBe("pending");
  });

  it("cross-tenant visibility and role held but not recorded owner", async () => {
    const tenantA = await createTenant("handover-smoke-3a", "growth");
    const tenantB = await createTenant("handover-smoke-3b", "growth");

    // give tenantA's admin the owner role too (multi-owner), but they are not the recorded owner
    const adminMember = await memberRepo.findMember(tenantA.org.id, tenantA.userIds.admin);
    await memberRepo.updateMemberRole(tenantA.org.id, adminMember!.id, "owner");
    const adminAsOwnerActor = { userId: tenantA.userIds.admin, orgId: tenantA.org.id, role: "owner" as const };

    await expect(
      orgService.initiateOwnershipHandover(adminAsOwnerActor, tenantA.org.id, tenantA.userIds.member),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    // cross-tenant orgId
    await expect(
      orgService.getPendingOwnershipHandover(tenantA.actors.owner, tenantB.org.id),
    ).rejects.toThrow();
  });
});
