/** The org's open offer, or `null`. Visible to any member of the workspace. */
export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);

  const existing = await handoverRepo.findPendingHandover(orgId);
  if (!existing) return null;

  const now = toIsoTimestamp(new Date());
  if (existing.expiresAt <= now) {
    await handoverRepo.resolveHandover(orgId, existing.id, "expired", null);
    return null;
  }

  return existing;
}

input.new_string:
/**
 * The org's open offer, or `null`. Visible to any member of the workspace.
 *
 * A read never persists the lazy `expired` transition: if it did, a mere
 * status check would rewrite the row before `acceptOwnershipHandover` or
 * `declineOwnershipHandover` got a chance to run, turning their `"expired"`
 * refusal into `"nothing_pending"` depending on who happened to look first.
 * Only an actual attempt to act on the offer (initiate/accept/decline/cancel)
 * settles it into a terminal status.
 */
export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);

  const existing = await handoverRepo.findPendingHandover(orgId);
  if (!existing) return null;

  const now = toIsoTimestamp(new Date());
  return existing.expiresAt <= now ? null : existing;
}

